const file=$input.first().json;
if(!file.sha || typeof file.content!=='string') throw new Error('GitHub não retornou SHA/conteúdo; validação cancelada para preservar os dados.');
let data; try { data=JSON.parse(Buffer.from(file.content.replace(/\s/g,''),'base64').toString('utf8')); } catch(e) { throw new Error('data/vagas.json inválido: '+e.message); }
if(!Array.isArray(data.vagas)) throw new Error('data/vagas.json não contém lista vagas.');
const safeUrl=value=>{try{const u=new URL(String(value||''));if(u.protocol!=='https:'||u.username||u.password||!u.hostname||u.hostname==='localhost'||u.hostname.endsWith('.localhost')||u.hostname==='127.0.0.1'||u.hostname==='::1'||/^10\.|^192\.168\.|^172\.(1[6-9]|2[0-9]|3[01])\./.test(u.hostname))return null;return u.href;}catch{return null;}};
const jobs=data.vagas.map((job,index)=>({job,index,checkedUrl:safeUrl(job.link)}));
return jobs.map(item=>({json:{...item,originalData:data,sha:file.sha}}));

const checks=$input.all();
const prepared=$('Preparar URLs originais').all();
const now=new Date().toISOString();
const closedRe=/(vaga|oportunidade|position|job|application|candidatura).{0,80}(encerrad[oa]|fechad[oa]|expirad[oa]|preenchid[oa]|nao est[aá] mais dispon[ií]vel|n[aã]o aceita mais candidaturas|no longer accepting|no longer available|position has been filled|job has been filled|applications are closed|this role is closed|job expired)/i;
const expiredRe=/(prazo|deadline|application deadline|data limite).{0,60}(expirad[oa]|encerrad[oa]|passad[oa]|closed|expired)|application deadline has passed/i;
const applyControlRe=/<form\b[^>]*(apply|application|candidatur)|<(button|a|input)\b[^>]*(apply|application|candidatur|candidate)|\b(apply now|apply for this job|apply for position|candidatar-se|candidate-se|enviar candidatura|inscreva-se)\b/i;
const results=[];
for(let i=0;i<prepared.length;i++){
 const p=prepared[i].json, r=checks[i]?.json||{};
 const status=Number(r.statusCode||r.status||0);
 const body=typeof r.body==='string'?r.body:typeof r.data==='string'?r.data:JSON.stringify(r.body||r.data||'');
 let state='PENDING_VALIDATION', reason='Não foi possível confirmar publicação e candidatura na página original.';
 const link=String(p.job?.link||'');
 if(!p.checkedUrl){state='PENDING_VALIDATION';reason='URL original inválida ou não HTTPS; nenhuma oportunidade é marcada ativa sem validação.';}
 else if(status===404||status===410){state='SOURCE_UNAVAILABLE';reason='Página original retornou HTTP '+status+'; remoção da página, sozinha, não confirma encerramento da vaga.';}
 else if(!status||status===401||status===403||status===429||status>=500){state='SOURCE_UNAVAILABLE';reason=status?'Fonte indisponível/restrita (HTTP '+status+').':'Erro de rede ao consultar a página original.';}
 else if(status>=200&&status<300){
   const job= p.job||{};
   const expiry=Date.parse(job.expiraEm||job.expiryDate||'');
   if(Number.isFinite(expiry)&&expiry<Date.now()){state='EXPIRED';reason='A data de expiração informada pela fonte já passou.';}
   else if(expiredRe.test(body)){state='EXPIRED';reason='A página indica que o prazo de candidatura expirou.';}
   else if(closedRe.test(body)){state='CLOSED';reason='A página original informa encerramento, preenchimento ou indisponibilidade da oportunidade.';}
   else if(applyControlRe.test(body)){state='ACTIVE';reason='Página original acessível e controle de candidatura encontrado; não foram detectadas mensagens de encerramento.';}
   else {state='PENDING_VALIDATION';reason='Página acessível, mas não foi encontrado formulário/botão de candidatura nem confirmação explícita de inscrições abertas.';}
 } else {state='PENDING_VALIDATION';reason='Resposta HTTP '+status+'; estado da candidatura não confirmado.';}
 results.push({...p.job,statusCandidatura:state,ultimaVerificacaoCandidatura:now,motivoVerificacaoCandidatura:reason,httpStatusVerificacao:status||null,urlVerificada:link});
}
const base=prepared[0]?.json;
if(!base) return [];
const data={...base.originalData,vagas:results,total:results.length,validacaoCandidaturasAtualizadaEm:now};
const content=Buffer.from(JSON.stringify(data,null,2)+'\n','utf8').toString('base64');
return [{json:{sha:base.sha,content,total:results.length,checkedAt:now,counts:results.reduce((a,j)=>(a[j.statusCandidatura]=(a[j.statusCandidatura]||0)+1,a),{})}}];
